# Adds a Home link to the vendor portal top bar
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\vendor\(protected)\layout.tsx"), $bytes)
Write-Host "UPDATED: src\app\vendor\(protected)\layout.tsx" -ForegroundColor Green
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan